INSERT INTO vendor_prospects (
  id, name, original_category, original_subcategory, category_key, brand, origin,
  address, district, city, phones, contact_name, email, notes, source_names,
  source_count, source_row, country_code, duplicate_key, has_phone, free_offer_eligible,
  campaign_status
) VALUES (
  'prsp_eg_0786', 'توكيل هيونداي : شارع الجمهوريه ( ادي ضهرك لسوبر ماركت خير زمان وخليك طوالي هتعدي تقاطع بعديها خليك باصص علي يمينك هتتلاقي مكتب مقفول و فيه عربيه فيرنا بيضا هتتلاقي التوكيل الناحيه التانيه من المكتب المقفول ده )توكيل شيفروليه و اوبل : شارع 23 يوليو ( خلي ضهرك للمتحف الحربي و امشي يمين شويه هتتلاقاه علي شمالك وهتتلاقه فوقيه فرع معهد اكسون )توكيل الهوندا عند على مسعد في 23 يوليوتوكيل اسبيرانزا : شارع الجمهوريه ( هتتلاقيه في طرف شارع الجمهوريه و الشارع ده موازي للممشي السياحي فخليك في طرف شارع الجمهوريه قصاد طرف الممشي السياحي من عند ديليسبس و ههتلاقي علي يمينك و انت ماشي في الجمهوريه قهوه علي بابا التوكيل في ضهرها علي طول هتتلاقي مكتب فيه عربيتين تيجو لونهم اسود و التوكيل مبيفتحش الا الصبح )و التلت توكيلات دول ليهم مركز صيانه معتمد في منطقه ال...... لساني مش عايز يقولها ( الحرفيين ) للاسفو ربنا معاكو و ارجو التثبيت و متججد باستمرار ان شاء الله اول ما اعرف جديد', 'تاجر', 'معرض/تاجر',
  'showroom', '', '', 'الغالي موتورز',
  'المركز الرئيسي', 'القاهرة', '{}', '',
  'khaled_alhashash@yahoo.com', 'الغالي موتورز تقدم اقوي عروض 2010فقط لعملاء فيات وجميع العملاءوجميع الماركات والموديلات نقدم (بونتو-جراند بونتو- برافو - لينيا - فيات500) وباسعار 2009 وعروض حقيقيه لجميع العملاء وتخفيضات بجد حقيقيه و اسئل عن الهدايا ت : 0224700459-0119009554-0121752793', 'التوكيلات', 1,
  786, 'EG', 'توكيلهيونداي:شارعالجمهوريه(اديضهركلسوبرماركتخيرزمانوخليكطواليهتعديتقاطعبعديهاخليكباصصعلييمينكهتتلاقيمكتبمقفولوفيهعربيهفيرنابيضاهتتلاقيالتوكيلالناحيهالتانيهمنالمكتبالمقفولده)توكيلشيفروليهواوبل:شارع23يوليو(خليضهركللمتحفالحربيوامشييمينشويههتتلاقاهعليشمالكوهتتلاقهفوقيهفرعمعهداكسون)توكيلالهونداعندعلىمسعدفي23يوليوتوكيلاسبيرانزا:شارعالجمهوريه(هتتلاقيهفيطرفشارعالجمهوريهوالشارعدهموازيللممشيالسياحيفخليكفيطرفشارعالجمهوريهقصادطرفالممشيالسياحيمنعندديليسبسوههتلاقيعلييمينكوانتماشيفيالجمهوريهقهوهعليباباالتوكيلفيضهرهاعليطولهتتلاقيمكتبفيهعربيتينتيجولونهماسودوالتوكيلمبيفتحشالاالصبح)والتلتتوكيلاتدولليهممركزصيانهمعتمدفيمنطقهال......لسانيمشعايزيقولها(الحرفيين)للاسفوربنامعاكووارجوالتثبيتومتججدباستمرارانشاءاللهاولمااعرفجديد_المركز الرئيسي', 0, 0,
  'new'
